typedef float rational_t;
#define START_PROF_TIMER(a) {}
#define STOP_PROF_TIMER(a) {}
#define assert(a) ((void)0)
#define NULL 0

class vector3d
{
public:
  float x, y, z;
};

class region_node;
class ai_polypath_cell;

class po
{
  char pad[48];
  vector3d abs_position;
public:
  const vector3d& get_abs_position() const { return abs_position; }
};

class entity
{
  char pad[80];
  po *my_po;
public:
  const vector3d& get_abs_position() const { return my_po->get_abs_position(); }
  region_node *get_primary_region() const;
};

class ai_path
{
  char data[4];
};

class ai_polypath
{
public:
  ai_polypath_cell* closest_cell(const vector3d& pt, region_node *reg = 0, entity *ent = 0) const;
  bool los_test(ai_polypath_cell* start_cell, const vector3d& start_pos, ai_polypath_cell* end_cell, const vector3d& end_pos);
  bool find_path(ai_path& path, ai_polypath_cell* start_cell, const vector3d& start_pos, ai_polypath_cell* end_cell, const vector3d& end_pos);
};

class world_dynamics_system
{
  char pad[928];
  ai_polypath *world_path;
public:
  ai_polypath *get_world_path() const { return world_path; }
};

extern world_dynamics_system *g_world_ptr;

class ai_locomotion
{
  char pad[32];
  ai_path my_path;
public:
  virtual bool set_path(const vector3d &dest, rational_t additional_weight_mod, bool force_path);
  void clear_path();
  entity *get_my_entity() const;
};

bool ai_locomotion::set_path( const vector3d& dest, rational_t additional_weight_mod, bool force_path )
{
  START_PROF_TIMER(proftimer_adv_AI_pathfinding);
  clear_path();

  bool path_it = false;

  ai_polypath *global_path = g_world_ptr->get_world_path();
  if(global_path != NULL)
  {
    const vector3d &start = get_my_entity()->get_abs_position();
    ai_polypath_cell *start_cell = global_path->closest_cell(start, get_my_entity()->get_primary_region(), get_my_entity());
    ai_polypath_cell *dest_cell  = global_path->closest_cell(dest, NULL, get_my_entity());

    assert(start_cell && dest_cell);

    if(!global_path->los_test(start_cell, start, dest_cell, dest))
      path_it = global_path->find_path(my_path, start_cell, start, dest_cell, dest);
  }

  STOP_PROF_TIMER(proftimer_adv_AI_pathfinding);

  return path_it;
}
